async function tryGaia() {
  const base = String($env.N8N_GAIACHAIN_API || $env.GAIACHAIN_API_ENDPOINT || '').trim();
  const key = String($env.N8N_GAIACHAIN_API_KEY || $env.GAIACHAIN_API_KEY || '').trim();
  if (!base) return { name: 'gaiachain', skipped: true, reason: 'N8N_GAIACHAIN_API vacío' };
  const statusPath = String($env.N8N_GAIACHAIN_STATUS_PATH || '/status').trim();
  const suffix = statusPath.startsWith('/') ? statusPath : '/' + statusPath;
  const url = base.replace(/\/$/, '') + suffix;
  try {
    const headers = { Accept: 'application/json' };
    if (key) headers.Authorization = 'Bearer ' + key;
    const r = await fetch(url, { method: 'GET', headers, redirect: 'manual' });
    return { name: 'gaiachain', url, http_status: r.status, ok: r.ok };
  } catch (e) {
    return { name: 'gaiachain', url, error: e.message };
  }
}

async function tryPowerBi() {
  const u = String($env.N8N_POWERBI_ENDPOINT || $env.POWER_BI_STREAMING_ENDPOINT || '').trim();
  if (!u) return { name: 'power_bi', skipped: true, reason: 'N8N_POWERBI_ENDPOINT vacío' };
  try {
    const r = await fetch(u, { method: 'HEAD', redirect: 'manual' });
    return { name: 'power_bi', http_status: r.status, ok: r.status < 500 };
  } catch (e) {
    return { name: 'power_bi', error: e.message };
  }
}

function slackEnv() {
  const ch = String($env.N8N_SLACK_CRITICAL || $env.N8N_SLACK_ALERTS || '').trim();
  const wh = String($env.SLACK_WEBHOOK || '').trim();
  return {
    name: 'slack',
    channel_configured: !!ch,
    webhook_configured: !!wh,
    note: 'Nodos Slack en UI deben usar Credencial OAuth o webhook; esto solo comprueba env.',
  };
}

function postgresHint() {
  const t = String($env.DB_TYPE || $env.N8N_DATABASE_TYPE || 'sqlite').toLowerCase();
  const pg = t.includes('postgres');
  return {
    name: 'postgres',
    skipped: !pg,
    n8n_database_type: t,
    note: pg ? 'Validar conexión con nodo Postgres y credencial en n8n' : 'SQLite por defecto: sin check TCP',
  };
}

const steps = [];
if (String($env.CASTUO_SKIP_EXTERNAL_VALIDATION || '') === '1') {
  return [
    {
      json: {
        allOk: true,
        skipped: true,
        reason: 'CASTUO_SKIP_EXTERNAL_VALIDATION=1',
        ts: new Date().toISOString(),
      },
    },
  ];
}

steps.push(await tryGaia());
steps.push(await tryPowerBi());
steps.push(slackEnv());
steps.push(postgresHint());

const hardFail = steps.filter((s) => s.error || (s.ok === false && !s.skipped));
const allOk = hardFail.length === 0;

return [
  {
    json: {
      allOk,
      steps,
      slack_message: allOk
        ? 'Sistema inicializado: chequeos básicos OK (revisar nodos reales Slack/Postgres en UI).'
        : 'Fallo validación: ' + hardFail.map((x) => x.name).join(', '),
      ts: new Date().toISOString(),
    },
  },
];
